{"annotations":{"narrativeDevelopmentsV1":[{"developmentType":"commitment","members":[],"narrativeModalityV1":"intent","narrativeVisibilityV1":{"audienceKeys":[],"class":"author-only","policyVersion":"author-review-v1"},"owners":[],"resolutionEvidenceKeys":[],"semanticSubKey":"sub:v1:a4e67e66-d5fe-4f97-adac-c413b4c3b786","state":"open","statement":"阿澈把借走的铜铃送回驿站。","transitions":[],"narrativeEvidenceV1":[{"evidenceKey":"return-promise","source":{"chapterId":null,"sourceUid":"res:v1:chapter:59fb1dc6-93a2-4884-b489-713f6e202cfa"},"fieldPointer":"/content","quote":"“等末班船靠了岸，我就把铃送回来。”阿澈说。","occurrence":0,"supportRole":"supports"},{"evidenceKey":"ringing-continues","source":{"chapterId":null,"sourceUid":"res:v1:chapter:59fb1dc6-93a2-4884-b489-713f6e202cfa"},"fieldPointer":"/content","quote":"天还没亮，铃声仍从河上断断续续地传来。","occurrence":0,"supportRole":"context"}]},{"developmentType":"goal","members":[],"narrativeModalityV1":"established","narrativeVisibilityV1":{"audienceKeys":[],"class":"unclassified","policyVersion":"author-review-v1"},"owners":[],"resolutionEvidenceKeys":["child-handed-over"],"semanticSubKey":"sub:v1:fdec587d-5595-4c8d-ae94-4876747681e2","state":"fulfilled","statement":"阿澈帮助第一名下船的孩子到岸上的人手中。","transitions":[],"narrativeEvidenceV1":[{"evidenceKey":"child-handed-over","source":{"chapterId":null,"sourceUid":"res:v1:chapter:59fb1dc6-93a2-4884-b489-713f6e202cfa"},"fieldPointer":"/content","quote":"父亲抓住抛下的缆绳。阿澈接住一个被送下来的孩子，孩子的手紧紧扣着他的领口。芦苇湾后面又露出一条船，船上的灯一会儿看得见，一会儿又被雨遮住。

“还有人！”父亲朝他喊。

阿澈把孩子交给岸上的妇人，重新走到水边。他的右手已经麻了，只得换左手握铃。铜铃的豁口硌进掌心，红了一小块。","occurrence":0,"supportRole":"supports"}]}]},"clearFields":[]}

